function pickOwner(agents, service, fallbackOwnerId) {
  const load = (a) => Number(a.open_leads || 0) / Math.max(1, Number(a.capacity || 1));
  const byLoad = (x, y) => load(x) - load(y) || String(x.agent_id).localeCompare(String(y.agent_id));
