function scoreLead(lead, enrich = {}) {
  const breakdown = [];
  let total = 0;
  const add = (factor, value, points, note) => {
    total += points;
    breakdown.push({ factor, value, points, note: note || '' });
  };

  // Enrichment fills gaps; it never overrides something the lead stated.
  const country = lead.country || enrich.country || '';
  const industryBucket = bucketIndustry(enrich.industry);

  // Hard disqualifier: an out-of-scope vertical is worth zero regardless of
  // every other signal, so it short-circuits before any points are awarded.
  if (industryBucket === 'excluded') {
    return {
      score: 0,
      band: 'unqualified',
      strategic: false,
      disqualified: true,
      disqualify_reason: `excluded industry: ${enrich.industry}`,
      breakdown: [{ factor: 'industry', value: enrich.industry, points: 0, note: 'excluded vertical, hard disqualify' }],
    };
  }

  const freeText = `${lead.free_text || ''} ${lead.service_interest || ''}`;
  if (C.DISQUALIFY_PATTERNS.test(freeText)) {
    add('intent_penalty', 'job/competitor/solicitation language',
      C.SCORE.penalty.competitor_or_jobseeker, 'matched the disqualify pattern');
  }

  const sizeB = bucketSize(enrich.company_size);
  add('company_size', sizeB, C.SCORE.company_size[sizeB],
    sizeB === 'unknown' ? 'not enriched, scored at the unknown band rather than zero' : '');

  add('industry', industryBucket, C.SCORE.industry[industryBucket],
    industryBucket === 'unknown' ? 'not enriched, scored at the unknown band rather than zero' : '');

  const marketB = bucketMarket(country);
  add('market', marketB, C.SCORE.market[marketB],
    lead.country ? '' : (country ? 'derived from the E.164 prefix' : 'no country signal'));

  const serviceB = bucketService(lead.service_interest);
  add('service', serviceB, C.SCORE.service[serviceB]);

  // Field names are the CANONICAL ones from _shared/intake.js. They were once
  // `stated_urgency` and `stated_budget` here and `urgency` and `budget_band`
  // there, which meant every real lead scored as though it had stated neither -
  // silently, because a missing field is a legal "unknown". Only a test that
  // ran intake and the scorer together caught it, which is why that test exists.
  const urgency = String(lead.urgency || 'unknown');
  add('urgency', urgency, C.SCORE.urgency[urgency] ?? C.SCORE.urgency.unknown);

  const hasEmail = !!lead.email_norm && C.EMAIL_RE.test(lead.email_norm);
  const hasPhone = !!lead.phone_key && lead.phone_key.length >= 10;
  const completeness = hasEmail && hasPhone ? 'both' : 'one';
  add('completeness', completeness, C.SCORE.completeness[completeness]);

  const src = String(lead.source || '').toLowerCase();
  add('source', src, C.SCORE.source[src] ?? 0);

  const budgetB = bucketBudget(lead.budget_band);
  add('budget', budgetB, C.SCORE.budget[budgetB]);

  const emailDomain = String(lead.email_norm || '').split('@')[1] || '';
  if (C.DISPOSABLE_EMAIL_DOMAINS.has(emailDomain)) {
    add('disposable_email', emailDomain, C.SCORE.penalty.disposable_email, 'throwaway inbox');
  }

  const raw = total;
  const score = Math.max(0, Math.min(C.SCORE.MAX, raw));
  if (raw !== score) breakdown.push({ factor: 'clamp', value: `${raw} -> ${score}`, points: 0, note: 'clamped to 0..100' });

  const strategic = String(enrich.strategic) === 'true' || enrich.strategic === true;
  if (strategic) breakdown.push({ factor: 'strategic_account', value: true, points: 0, note: 'forces the VIP band regardless of score' });

  return { score, band: C.bandFor(score, strategic), strategic, disqualified: false, breakdown };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { scoreLead, bucketSize, bucketIndustry, bucketMarket, bucketService, bucketBudget };
}

/**
 * Lead Intelligence Pipeline - intake runtime.
 *
 * Everything that turns a source-specific payload into the canonical lead, and
 * decides whether that lead is usable. It lives here, not in the workflow, for
 * one reason: this is the code most likely to be wrong, so it is the code that
 * has to be unit-testable outside n8n (`node scripts/test-intake.js`).
 *
 * The three source normalisers in LP-01 therefore do only the part that is
 * genuinely different per source - which field is called what - and hand the
 * result to `finalizeLead`, so phone parsing, email folding, key derivation and
 * validation happen exactly once in the whole system.
 */

const INTAKE = {
  // A bulk import is accepted synchronously, so it has to fit inside a webhook
  // response window. 200 rows is comfortable; above it the endpoint refuses the
  // batch with a message naming the limit, rather than timing out halfway and
  // leaving the caller unable to tell what landed.
  MAX_CSV_ROWS: 200,
  MAX_FREE_TEXT: 4000,
  MAX_RAW_JSON: 4000,
  MIN_PHONE_DIGITS: 8,
  MAX_PHONE_DIGITS: 15,
};

// ---------------------------------------------------------------------------
// Small text helpers
// ---------------------------------------------------------------------------

/** Trim, collapse runs of whitespace, drop control characters, cap length. */
function clean(v, max) {
  return String(v ?? '')
    .replace(/[\x00-\x1f\x7f]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max || 200);
}

// Hoisted to constants rather than returned as inline array literals.
//
// The reason is not style. This whole file is inlined into every Code node in
// every workflow by scripts/build-workflows.js, and n8n's workflow validator
// scans a Code node's source for a return statement followed by an array
// literal, to check that the node yields items shaped {json: ...}. A helper
// that returns an array of STRINGS reads to that check as a malformed return,
// and it reported the error against all 209 nodes at once - a false positive,
// but one that makes a genuine error impossible to find.
//
// The check does not skip comments either, so this note deliberately describes
// the pattern instead of quoting it. A shared prelude means one file's habits
// propagate to every node in the system, including its accidents.
const CONSENT_YES = ['true', 'yes', 'y', '1', 'granted', 'agree', 'agreed', 'opted_in', 'opt-in', 'on', 'checked'];
const CONSENT_NO = ['false', 'no', 'n', '0', 'denied', 'declined', 'refused', 'unsubscribed', 'off'];

function truthy(v) {
  const s = String(v ?? '').trim().toLowerCase();
  return CONSENT_YES.includes(s);
}

function falsy(v) {
  const s = String(v ?? '').trim().toLowerCase();
  return CONSENT_NO.includes(s);
}

// ---------------------------------------------------------------------------
// Country
// ---------------------------------------------------------------------------
// The reverse of DIAL_PREFIXES. Built once from the same table, so the two can
// never disagree - a hand-written second map is a bug waiting for the first
// time someone adds a market to one of them.

const ISO_TO_CC = (() => {
  const m = {};
  for (const [cc, iso] of C.DIAL_PREFIXES) if (!m[iso]) m[iso] = cc;
  return m;
})();

// Only the markets this business actually sees. An unrecognised country name
// resolves to '' and the country is then derived from the phone number, which
// is more reliable than a guessed string match.
const COUNTRY_NAMES = {
  egypt: 'EG', 'misr': 'EG', 'مصر': 'EG',
  uae: 'AE', 'united arab emirates': 'AE', dubai: 'AE', 'abu dhabi': 'AE', 'الإمارات': 'AE',
  'saudi arabia': 'SA', saudi: 'SA', ksa: 'SA', riyadh: 'SA', 'السعودية': 'SA',
  qatar: 'QA', kuwait: 'KW', bahrain: 'BH', oman: 'OM', jordan: 'JO', lebanon: 'LB',
  morocco: 'MA', tunisia: 'TN', algeria: 'DZ', iraq: 'IQ', sudan: 'SD', libya: 'LY',
  'united kingdom': 'GB', uk: 'GB', england: 'GB', britain: 'GB',
  usa: 'US', 'united states': 'US', us: 'US', america: 'US',
  germany: 'DE', france: 'FR', india: 'IN',
};

function isoFrom(raw) {
  const s = clean(raw, 60).toLowerCase();
  if (!s) return '';
  if (/^[a-z]{2}$/.test(s) && Object.prototype.hasOwnProperty.call(ISO_TO_CC, s.toUpperCase())) {
    return s.toUpperCase();
  }
  return COUNTRY_NAMES[s] || '';
}

// ---------------------------------------------------------------------------
// Service, urgency and budget - derived deterministically, never by the model
// ---------------------------------------------------------------------------
// These three feed the score, and the score has to be reproducible and
// explainable, so all three are regex over text the lead actually wrote. The AI
// reads the same free text for a *qualitative* read and contributes zero
// points; see constants.js section 5.

// A word STEM must not be wrapped in a closing \b. `/\bautomat\b/` matches
// nothing, because "automation" has no boundary after "automat" - so the whole
// pattern silently never fires and every lead scores as service "unknown".
// It shipped that way for exactly one test run. Stems therefore end in \w*,
// and only whole words keep a closing \b.
//
// Order is priority: the first match wins, so the specific and high-value
// categories are listed before the generic ones.
const SERVICE_PATTERNS = [
  [/\b(rag|knowledge ?base|document (search|q ?& ?a)|vector (db|search|store)|semantic search)\b/i, 'rag'],
  [/\b(chat ?bots?|ai ?agents?|voice ?agents?|assistants?|copilots?|llms?)\b/i, 'ai_agent'],
  [/\b(automat\w*|n8n|zapier|make\.com|workflows?)/i, 'automation'],
  [/(أتمتة|اتمتة|أتمته|أوتوميشن|اوتوميشن)/, 'automation'],
  [/(شات ?بوت|مساعد ذكي|وكيل ذكاء)/, 'ai_agent'],
  [/(ربط|تكامل|دمج أنظمة|دمج انظمة)/, 'integration'],
  [/(استشار|خطة عمل)/, 'consulting'],
  [/(تدريب|كورس|ورشة)/, 'training'],
  [/\b(integrat\w*|apis?|webhooks?|middleware|connectors?)\b/i, 'integration'],
  [/\b(web ?app|mobile ?app|portal|dashboard|platform|full[- ]?stack|saas|website)s?\b/i, 'custom_app'],
  [/\b(consult\w*|advis\w*|strateg\w*|roadmaps?)/i, 'consulting'],
  [/\b(audit\w*|assessments?|health ?check)/i, 'audit'],
  [/\b(train(ing|er|ers)?|workshops?|courses?|upskill\w*)\b/i, 'training'],
];

function normService(raw, freeText) {
  for (const text of [clean(raw, 200), clean(freeText, 600)]) {
    if (!text) continue;
    for (const [re, token] of SERVICE_PATTERNS) if (re.test(text)) return token;
  }
  return 'unknown';
}

// Same stem rule as SERVICE_PATTERNS above: "urgently" does not match
// /\burgent\b/.
const URGENCY_PATTERNS = [
  [/\b(asap|urgent\w*|immediat\w*|right away|this week|by (monday|tuesday|wednesday|thursday|friday)|today|tonight|deadline)/i, 'immediate'],
  [/(ضروري|حالا|حالاً|عاجل|بسرعة|في أقرب وقت|النهاردة|النهارده)/, 'immediate'],
  [/\b(this month|next month|this quarter|q[1-4] |within (a|one|two|2) months?|30 days|60 days)/i, 'this_quarter'],
  [/(قريب|الشهر ده|الشهر الجاي|خلال شهر|خلال شهرين)/, 'this_quarter'],
  [/\b(explor\w*|research\w*|just looking|curious|no rush|someday|in the future|later|eventually)/i, 'exploring'],
  [/(بستكشف|بستفسر|مجرد استفسار|مش مستعجل|لسه بفكر)/, 'exploring'],
];

function normUrgency(raw, freeText) {
  const direct = clean(raw, 40).toLowerCase().replace(/[\s-]+/g, '_');
  if (['immediate', 'this_quarter', 'exploring'].includes(direct)) return direct;
  for (const text of [clean(raw, 200), clean(freeText, 600)]) {
    if (!text) continue;
    for (const [re, token] of URGENCY_PATTERNS) if (re.test(text)) return token;
  }
  return 'unknown';
}

// Thresholds come from constants.js so intake and the scorer cannot disagree
// about what "high" means. Only an explicit amount or an explicit band counts:
// a number with no currency is NOT assumed to be dollars, because "budget: 50"
// is far more likely to be a typo or a headcount than fifty dollars, and a
// wrong budget band can move a lead across a qualification threshold.
const BUDGET = C.BUDGET_USD;

function normBudget(raw, freeText) {
  const direct = clean(raw, 40).toLowerCase();
  if (['high', 'mid', 'medium', 'low'].includes(direct)) return direct === 'medium' ? 'mid' : (direct === 'low' ? 'unknown' : direct);

  const scan = `${clean(raw, 200)} ${clean(freeText, 600)}`;
  // $12,000 / 12000 usd / 12k usd / usd 12000
  const m = scan.match(/(?:\$|\busd\s*)\s*([\d,.]+)\s*(k|m)?\b|\b([\d,.]+)\s*(k|m)?\s*(?:usd|dollars?|\$)\b/i);
  if (!m) return 'unknown';
  const num = parseFloat(String(m[1] || m[3] || '').replace(/,/g, ''));
  if (!isFinite(num) || num <= 0) return 'unknown';
  const mult = String(m[2] || m[4] || '').toLowerCase();
  const usd = num * (mult === 'k' ? 1000 : mult === 'm' ? 1000000 : 1);
  if (usd >= BUDGET.HIGH) return 'high';
  if (usd >= BUDGET.MID) return 'mid';
  return 'unknown';
}

// ---------------------------------------------------------------------------
// finalizeLead - the one place a canonical lead is constructed
// ---------------------------------------------------------------------------

/**
 * @param p    source-mapped partial: full_name, email_raw, phone_raw, company,
 *             country, service_interest, free_text, consent, budget, urgency,
 *             source, source_ref, sub_source, raw
 * @param ctx  { now: epochSeconds, default_cc: '20' }
 */
function finalizeLead(p, ctx) {
  ctx = ctx || {};
  const now = Number(ctx.now || Math.floor(Date.now() / 1000));

  const full_name = clean(p.full_name, 120);
  const company = clean(p.company, 160);

  // --- email ---------------------------------------------------------------
  const email_raw = clean(p.email_raw, 200).toLowerCase();
  const email_valid = !!email_raw && C.EMAIL_RE.test(email_raw);
  const email_norm = email_valid ? C.normEmail(email_raw) : '';

  // --- phone ---------------------------------------------------------------
  // Country is resolved BEFORE the phone, because a stated country picks the
  // dialling code for a local-format number. Without that, a UAE lead writing
  // "0501234567" becomes an Egyptian number and lands in the wrong market band.
  const stated_country = isoFrom(p.country);
  const cc = ISO_TO_CC[stated_country] || String(ctx.default_cc || '20');

  const phone_raw = clean(p.phone_raw, 40);
  const phone_digits = phone_raw.replace(/\D/g, '');
  const phone_valid = phone_digits.length >= INTAKE.MIN_PHONE_DIGITS
    && phone_digits.length <= INTAKE.MAX_PHONE_DIGITS;
  const phone_e164 = phone_valid ? C.toE164(phone_raw, cc) : '';
  const phone_key = phone_valid ? C.phoneKey(phone_e164) : '';

  const country = stated_country || C.countryFromE164(phone_e164);

  // --- consent -------------------------------------------------------------
  // Three states, never two. "unknown" is not "denied" and it is not "granted";
  // it is a lead that has to be asked before anything is sent to it.
  let consent = 'unknown';
  if (truthy(p.consent)) consent = 'granted';
  else if (falsy(p.consent)) consent = 'denied';

  const free_text = clean(p.free_text, INTAKE.MAX_FREE_TEXT);
  const service_interest = normService(p.service_interest, free_text);

  const lead = {
    lead_uid: '',
    source: String(p.source || '').trim(),
    source_ref: clean(p.source_ref, 120),
    sub_source: clean(p.sub_source, 60),
    received_at: now,

    full_name,
    email_raw,
    email_norm,
    phone_raw,
    phone_e164,
    phone_key,
    country,
    company,
    domain: C.domainOf(email_norm),

    service_interest,
    urgency: normUrgency(p.urgency, free_text),
    budget_band: normBudget(p.budget, free_text),
    free_text,

    consent,
    consent_source: clean(p.consent_source, 40) || 'unspecified',

    // filled downstream by LP-02 and later
    score: 0,
    band: '',
    owner_id: '',
    odoo_lead_id: 0,
    status: 'active',

    raw_json: JSON.stringify(p.raw ?? {}).slice(0, INTAKE.MAX_RAW_JSON),
    updated_at: now,
  };

  // --- the two keys --------------------------------------------------------
  // person_key answers "have we met this human?"; idem_key answers "have we
  // already processed this delivery?". Conflating them is the classic intake
  // bug in both directions - see constants.js section 3.
  lead.person_key = C.personKeyOf(lead);
  lead.idem_key = C.intakeIdemKey(lead.source, lead.source_ref, lead.person_key, p.raw ?? p);
  lead.lead_uid = C.leadUidFrom(lead.idem_key, lead.received_at);

  const v = validateLead(lead);
  lead.validation_state = v.state;
  lead.validation_missing = v.missing.join(',');
  lead.validation_reason = v.reason;
  return lead;
}

/**
 * Four outcomes, and the difference between them is what the whole intake
 * routing hangs on:
 *
 *   ok          - complete enough to score
 *   incomplete  - reachable, but missing a critical field. Goes FORWARD, into
 *                 the Data Completion funnel stage. Not an error.
 *   unusable    - nobody to contact. Quarantined; there is no follow-up that
 *                 could ever recover it.
 *   parse_error - the row could not be read at all. Quarantined, with the raw
 *                 text kept so it can be fixed and replayed.
 */
function validateLead(lead) {
  const contactable = !!lead.email_norm || !!lead.phone_key;
  const missing = [];
  if (!lead.full_name) missing.push('full_name');
  if (!contactable) missing.push('contactable');
  if (lead.consent === 'unknown') missing.push('consent');

  if (!contactable) {
    return { state: 'unusable', missing, reason: 'no valid email and no valid phone - nothing to contact' };
  }
  if (missing.length) {
    return { state: 'incomplete', missing, reason: 'missing ' + missing.join(', ') };
  }
  return { state: 'ok', missing: [], reason: '' };
}

// ---------------------------------------------------------------------------
// CSV
// ---------------------------------------------------------------------------

/**
 * A real CSV reader, not a `split(',')`.
 *
 * Quoted fields, doubled quotes, embedded commas and newlines, CRLF, and a BOM
 * all appear in files exported from Excel, and every one of them turns a
 * `split(',')` import into silent data corruption - which is worse than a
 * failed import, because nobody notices.
 *
 * Errors are attached PER ROW. An unreadable row must not take the batch down
 * with it (edge case 13).
 */
function parseCsv(text) {
  const src = String(text || '').replace(/^\uFEFF/, '');
  const rows = [];
  let field = '';
  let row = [];
  let inQuotes = false;
  let i = 0;

  while (i < src.length) {
    const ch = src[i];
    if (inQuotes) {
      if (ch === '"') {
        if (src[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i += 1; continue;
      }
      field += ch; i += 1; continue;
    }
    if (ch === '"' && field === '') { inQuotes = true; i += 1; continue; }
    if (ch === ',') { row.push(field); field = ''; i += 1; continue; }
    if (ch === '\r') { i += 1; continue; }
    if (ch === '\n') { row.push(field); rows.push(row); row = []; field = ''; i += 1; continue; }
    field += ch; i += 1;
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }

  const nonEmpty = rows.filter((r) => r.some((c) => String(c).trim() !== ''));
  if (!nonEmpty.length) return { header: [], rows: [], error: 'the file is empty' };

  const header = nonEmpty[0].map((h) => clean(h, 60).toLowerCase());
  const out = [];
  for (let r = 1; r < nonEmpty.length; r++) {
    const cells = nonEmpty[r];
    let error = '';
    if (cells.length !== header.length) {
      error = `expected ${header.length} columns, found ${cells.length}`;
    } else if (inQuotes && r === nonEmpty.length - 1) {
      error = 'unterminated quote - the rest of the file was swallowed into this row';
    }
    out.push({ line: r + 1, cells, error });
  }
  return { header, rows: out, error: '' };
}

// Header spellings seen in real exports. Anything unrecognised is ignored
// rather than guessed at, and unrecognised headers are reported back in the
// response so the importer can fix the file instead of wondering why a column
// had no effect.
const CSV_ALIASES = {
  full_name: ['full_name', 'full name', 'name', 'contact', 'contact name', 'customer', 'customer name', 'lead name', 'الاسم'],
  email_raw: ['email', 'e-mail', 'email address', 'mail', 'work email', 'الايميل', 'البريد'],
  phone_raw: ['phone', 'mobile', 'phone number', 'mobile number', 'tel', 'telephone', 'whatsapp', 'الموبايل', 'التليفون'],
  company: ['company', 'company name', 'organisation', 'organization', 'account', 'business', 'الشركة'],
  country: ['country', 'market', 'location', 'الدولة'],
  service_interest: ['service', 'service interest', 'interested in', 'product', 'offering', 'الخدمة'],
  free_text: ['notes', 'note', 'message', 'requirement', 'requirements', 'need', 'description', 'comments', 'ملاحظات'],
  consent: ['consent', 'opt_in', 'opt-in', 'optin', 'gdpr', 'marketing consent', 'subscribed'],
  budget: ['budget', 'budget usd', 'deal size', 'value'],
  urgency: ['urgency', 'timeline', 'timeframe', 'when'],
  sub_source: ['source', 'lead source', 'channel', 'campaign'],
  source_ref: ['id', 'row id', 'record id', 'external id', 'crm id'],
};

function csvHeaderMap(header) {
  const map = {};
  const used = new Set();
  for (const [field, aliases] of Object.entries(CSV_ALIASES)) {
    for (let i = 0; i < header.length; i++) {
      if (aliases.includes(header[i]) && !used.has(i)) { map[field] = i; used.add(i); break; }
    }
  }
  const unmapped = header.filter((h, i) => h && !used.has(i));
  return { map, unmapped };
}

function mapCsvRow(map, cells) {
  const at = (f) => (map[f] === undefined ? '' : cells[map[f]]);
  return {
    full_name: at('full_name'),
    email_raw: at('email_raw'),
    phone_raw: at('phone_raw'),
    company: at('company'),
    country: at('country'),
    service_interest: at('service_interest'),
    free_text: at('free_text'),
    consent: at('consent'),
    budget: at('budget'),
    urgency: at('urgency'),
    sub_source: at('sub_source'),
    source_ref: at('source_ref'),
  };
}

const I = {
  INTAKE, clean, truthy, falsy, ISO_TO_CC, COUNTRY_NAMES, isoFrom,
  SERVICE_PATTERNS, normService, URGENCY_PATTERNS, normUrgency, BUDGET, normBudget,
  finalizeLead, validateLead, parseCsv, CSV_ALIASES, csvHeaderMap, mapCsvRow,
};

if (typeof module !== 'undefined' && module.exports) module.exports = I;

// ===== END shared runtime =====
const ctx = $('Assign Owner').first().json;
const lead = ctx.lead;
const v = ctx.v;

const claim = $input.all().map(i => i.json)
  .find(r => r && r.idem_key === ctx.upsert_key && r.scope !== undefined);

// --- the receipt check ---------------------------------------------------
// A ledger row in state 'done' carries the Odoo id it produced. Combined with
// the search above, this is the full answer to "did the last run get through?"
//   done            -> we have the id, update it
//   claimed, found  -> the write landed and the acknowledgement did not (EC-7)
//   claimed, absent -> the write never landed, create
const claimedBefore = !!claim && claim.state === 'claimed';
const alreadyDone = !!claim && claim.state === 'done' && Number(claim.result_ref) > 0;

let target_id = 0;
let method = 'create';
let recovery = '';

if (alreadyDone) {
  target_id = Number(claim.result_ref);
  method = 'write';
  recovery = 'the ledger already holds Odoo id ' + target_id + ' for this lead';
} else if (ctx.dup_action === 'update_self' || ctx.dup_action === 'merge_into') {
  target_id = ctx.dup_target_id;
  method = 'write';
  if (claimedBefore && ctx.dup_action === 'update_self') {
    recovery = 'PARTIAL SUCCESS RECOVERED: the ledger says claimed but never completed, and Odoo already holds opportunity ' +
      target_id + ' under this external key. The previous run created it and lost the response.';
  }
} else if (claimedBefore) {
  recovery = 'a previous attempt claimed this key but Odoo has no matching record, so the write genuinely never landed. Creating.';
}

// --- the payload ---------------------------------------------------------
const title = [lead.company || lead.full_name || 'Inbound lead',
  lead.service_interest && lead.service_interest !== 'unknown' ? lead.service_interest.replace(/_/g, ' ') : '']
  .filter(Boolean).join(' - ');

const PRIORITY = { vip: '3', qualified: '2', nurture: '1' };

const values = {
  name: title.slice(0, 120),
  type: 'opportunity',
  contact_name: lead.full_name || '',
  email_from: lead.email_raw || lead.email_norm || '',
  phone: lead.phone_e164 || lead.phone_raw || '',
  partner_name: lead.company || '',
  description: [
    'Source: ' + lead.source + (lead.sub_source ? ' / ' + lead.sub_source : ''),
    'Lead id: ' + lead.lead_uid,
    'Score: ' + v.score + '  Band: ' + ctx.band + (ctx.band_overridden ? ' (overridden: ' + ctx.dup_reason + ')' : ''),
    'Consent: ' + lead.consent + ' (' + lead.consent_source + ')',
    v.ai_status === 'ok'
      ? 'AI read: ' + v.ai_intent + ' intent, confidence ' + v.ai_confidence + '. ' + v.ai_reason
      : 'AI read: ' + v.ai_status + (v.ai_note ? ' (' + v.ai_note + ')' : ''),
    '',
    'What they wrote:',
    lead.free_text || '(nothing)',
  ].join('\n').slice(0, 4000),
  x_lp_lead_id: lead.lead_uid,
  stage_id: ctx.stage_id,
  priority: PRIORITY[ctx.band] || '0',
};

if (ctx.odoo_user_id > 0) values.user_id = ctx.odoo_user_id;

// Closing is a field change, not a stage change.
if (ctx.close) {
  values.active = false;
  values.probability = 0;
}

// --- a merge ENRICHES the survivor, it does not overwrite it -------------
// The full payload above describes THIS enquiry. Writing it onto an existing
// opportunity for the same person is destructive, and the first live run
// proved it: a WhatsApp follow-up merged into a website lead blanked the
// opportunity's email (WhatsApp has none) and, far worse, replaced its
// x_lp_lead_id with the second lead's - destroying the original's idempotency
// anchor, so a later replay of the first lead would no longer find it and
// would create the duplicate this whole path exists to prevent.
//
// So a merge writes only into fields that are currently empty, and never
// touches the external key, the stage, the owner or the description. The new
// enquiry is recorded as a chatter note instead, where it reads as history
// rather than as a silent overwrite.
let payload = values;
if (ctx.dup_action === 'merge_into') {
  const ex = ctx.dup_existing || {};
  const blank = (v) => v === false || v === null || v === undefined || String(v).trim() === '';
  payload = {};
  if (blank(ex.email_from) && (lead.email_raw || lead.email_norm)) payload.email_from = lead.email_raw || lead.email_norm;
  if (blank(ex.phone) && lead.phone_e164) payload.phone = lead.phone_e164;
  if (blank(ex.partner_name) && lead.company) payload.partner_name = lead.company;
  if (blank(ex.contact_name) && lead.full_name) payload.contact_name = lead.full_name;
  // An empty write is legal here - measured, crm.lead write([id], {}) returns
  // true - and it keeps the flow uniform: every path still produces a gateway
  // call whose result confirms the opportunity id.
}

const args = method === 'create' ? [[payload]] : [[target_id], payload];

return [{ json: {
  ...ctx,
  odoo_method: method,
  odoo_target_id: target_id,
  odoo_args_json: JSON.stringify(args),
  recovery,
  claim_state_before: claim?.state || 'none',
  claimed_at: Math.floor(Date.now() / 1000),
} }];

// ===== BEGIN shared runtime, generated from 02_Workflows/_shared/ =====
// Do not edit here. Edit the source files and re-run scripts/build-workflows.js.
// The same source is unit-tested by scripts/test-scoring.js and test-intake.js.
/**
 * Lead Intelligence Pipeline - canonical constants.
 *
 * n8n Code nodes cannot import files, so the relevant slice of this file is
 * inlined into each node. THIS FILE IS THE SOURCE OF TRUTH: change it here
 * first, then propagate. Every inlined copy carries the comment
 * `// from _shared/constants.js` so the copies are greppable.
 *
 * Nothing here reads a secret. Per-deployment values live in each workflow's
 * `Config` node, because this n8n instance runs with
 * N8N_BLOCK_ENV_ACCESS_IN_NODE=true and $env throws.
 */

// ---------------------------------------------------------------------------
// 1. Canonical lead schema
// ---------------------------------------------------------------------------
// Every source is normalised into exactly this shape before anything else
// looks at it. `raw_json` keeps the original payload so a replay can prove
// what actually arrived.

const LEAD_SCHEMA = {
  lead_uid: 'string', // LP-<yyyymmdd>-<8 hex>, generated once at intake
  source: 'string', // website | whatsapp | csv_import
  source_ref: 'string', // provider id when the source gives one (wamid, form id, csv row)
  received_at: 'number', // epoch seconds
  full_name: 'string',
  email_raw: 'string',
  email_norm: 'string', // lowercased, gmail dots/plus-tags folded
  phone_raw: 'string',
  phone_e164: 'string', // +<cc><national>, digits only after the +
  phone_key: 'string', // trailing 10 digits, the comparison key
  country: 'string', // ISO-2, derived from the E.164 prefix when not supplied
  company: 'string',
  domain: 'string', // from email_norm when it is not a free provider
  service_interest: 'string',
  free_text: 'string', // the "what do you need" blob the AI reads
  consent: 'string', // granted | denied | unknown
  consent_source: 'string', // form_checkbox | inbound_initiated | import_attested
  // --- filled downstream ---
  score: 'number',
  score_breakdown_json: 'string',
  band: 'string', // vip | qualified | nurture | unqualified | data_completion | manual_review
  ai_status: 'string', // ok | unavailable | skipped
  ai_intent: 'string', // high | medium | low
  ai_urgency: 'string',
  ai_signals: 'string',
  ai_reason: 'string',
  ai_confidence: 'number',
  owner_id: 'string',
  assign_rung: 'number', // which fallback rung assigned it, 1..3
  odoo_lead_id: 'number',
  odoo_stage: 'string',
  approval_state: 'string', // not_required | pending | approved | rejected
  approval_by: 'string',
  status: 'string', // active | merged | closed
  merged_into: 'string', // lead_uid of the survivor, when this one lost a dedupe
  raw_json: 'string',
  updated_at: 'number',
};

// Critical fields. Missing any of these routes to the Data Completion path
// instead of scoring. `service_interest` is deliberately NOT critical: it is
// recoverable from free text and from the follow-up conversation, and making
// it critical sent most WhatsApp leads to a human for no reason.
const CRITICAL_FIELDS = ['full_name', 'contactable', 'consent'];
// `contactable` is satisfied by EITHER a valid email OR a valid phone.

// ---------------------------------------------------------------------------
// 2. Normalisation
// ---------------------------------------------------------------------------

// Country dial prefixes, longest-first so +1868 beats +1.
// Only the markets this business actually sees; everything else resolves to ''.
const DIAL_PREFIXES = [
  ['971', 'AE'], ['966', 'SA'], ['974', 'QA'], ['965', 'KW'], ['973', 'BH'],
  ['968', 'OM'], ['962', 'JO'], ['961', 'LB'], ['212', 'MA'], ['216', 'TN'],
  ['213', 'DZ'], ['249', 'SD'], ['218', 'LY'], ['964', 'IQ'],
  ['20', 'EG'], ['44', 'GB'], ['49', 'DE'], ['33', 'FR'], ['91', 'IN'],
  ['1', 'US'],
];

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com',
  'live.com', 'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
  'yandex.com', 'mail.com', 'gmx.com',
]);

const DISPOSABLE_EMAIL_DOMAINS = new Set([
  'mailinator.com', 'tempmail.com', 'guerrillamail.com', '10minutemail.com',
  'throwaway.email', 'yopmail.com', 'trashmail.com', 'sharklasers.com',
]);

/**
 * Digits-only, then take the trailing 10 as the comparison key.
 * Ported from projects/accounts/belal/tooling/contacts-parser/parse_contacts.py,
 * where it deduped 23.5k real contacts down to 12,866. The trailing-10 rule is
 * what makes "01012345678", "+201012345678" and "0020 101 234 5678" one person.
 */
function phoneKey(raw) {
  const d = String(raw || '').replace(/\D/g, '');
  return d.length >= 10 ? d.slice(-10) : d;
}

/**
 * Best-effort E.164. `defaultCc` is the deployment's home country, used only
 * when the number carries no international prefix of its own.
 */
function toE164(raw, defaultCc = '20') {
  let d = String(raw || '').replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);
  // A local number: drop the trunk 0 and prepend the home country code.
  if (d.startsWith('0')) d = defaultCc + d.slice(1);
  // Already-national length with no country code at all.
  else if (d.length <= 10) d = defaultCc + d;
  return '+' + d;
}

function countryFromE164(e164) {
  const d = String(e164 || '').replace(/\D/g, '');
  for (const [pfx, iso] of DIAL_PREFIXES) if (d.startsWith(pfx)) return iso;
  return '';
}

/**
 * Fold an email to a comparison key. Gmail ignores dots and everything after
 * a plus, so a.b+lead@gmail.com and ab@gmail.com are the same inbox - and the
 * same person submitting twice.
 */
function normEmail(raw) {
  const s = String(raw || '').trim().toLowerCase();
  const at = s.lastIndexOf('@');
  if (at < 1) return '';
  let [user, domain] = [s.slice(0, at), s.slice(at + 1)];
  if (domain === 'googlemail.com') domain = 'gmail.com';
  if (domain === 'gmail.com') user = user.split('+')[0].replace(/\./g, '');
  else user = user.split('+')[0];
  return `${user}@${domain}`;
}

const EMAIL_RE = /^[^\s@]+@[^\s@.]+\.[^\s@]{2,}$/;

function domainOf(emailNorm) {
  const d = String(emailNorm || '').split('@')[1] || '';
  return FREE_EMAIL_DOMAINS.has(d) ? '' : d;
}

// ---------------------------------------------------------------------------
// 3. Identity and idempotency - two different things
// ---------------------------------------------------------------------------
// `idem_key` identifies an EVENT: "has this exact delivery been processed?"
// `person_key` identifies a HUMAN: "have we met this person before?"
// The same person arriving on WhatsApp and the website produces two different
// event keys, both correctly accepted, and one person key that decides which
// lead record survives. Conflating them is the classic bug: dedupe by event
// key and the second source is silently dropped; dedupe by person key and a
// retried webhook overwrites good data.

const IDEM_SCOPES = ['intake', 'odoo_upsert', 'message', 'booking', 'approval'];

/**
 * FNV-1a 64-bit in BigInt: exact, dependency-free, and identical in a Code
 * node and in `node scripts/*`. Not a security hash and not used as one.
 */
function stableHash(str) {
  let h = 0xcbf29ce484222325n;
  const prime = 0x100000001b3n;
  const mask = 0xffffffffffffffffn;
  const s = String(str);
  for (let i = 0; i < s.length; i++) {
    h ^= BigInt(s.charCodeAt(i) & 0xff);
    h = (h * prime) & mask;
  }
  return h.toString(16).padStart(16, '0');
}

/** Key order must not change the hash, so serialise with sorted keys. */
function canonicalJson(v) {
  if (v === null || typeof v !== 'object') return JSON.stringify(v ?? null);
  if (Array.isArray(v)) return `[${v.map(canonicalJson).join(',')}]`;
  return `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(v[k])}`).join(',')}}`;
}

/**
 * Stable across retries, distinct across genuinely separate submissions.
 *
 * A provider id is always preferred. When there is none, the key is a hash of
 * the submission's own content - NOT a time bucket. Time bucketing was the
 * first design and it is fragile at the boundary: two clicks five seconds
 * apart can straddle a bucket edge and both be accepted, which is exactly the
 * duplicate the gate exists to stop. A content hash has no boundary.
 *
 * The accepted trade-off: a person who submits a byte-identical form twice a
 * week apart is treated as one event. That is the correct reading of an
 * identical request, and the second delivery still writes an
 * `intake_duplicate_event` audit row, so it is visible rather than silent.
 */
function intakeIdemKey(source, sourceRef, personKey, payload) {
  if (sourceRef) return `intake:${source}:${sourceRef}`;
  return `intake:${source}:${personKey}:${stableHash(canonicalJson(payload))}`;
}

/** Deterministic, so a replay of the same event rebuilds the same id. */
function leadUidFrom(idemKey, receivedAtSec) {
  const d = new Date(Number(receivedAtSec || 0) * 1000);
  const ymd = `${d.getUTCFullYear()}${String(d.getUTCMonth() + 1).padStart(2, '0')}${String(d.getUTCDate()).padStart(2, '0')}`;
  return `LP-${ymd}-${stableHash(idemKey).slice(0, 8).toUpperCase()}`;
}

function personKeyOf(lead) {
  return lead.phone_key || lead.email_norm || `uid:${lead.lead_uid}`;
}

// ---------------------------------------------------------------------------
// 4. Duplicate confidence
// ---------------------------------------------------------------------------
// Never delete. High confidence merges into the survivor; medium raises a
// manual-review case; low is treated as a new person.

const DUP = {
  HIGH: 0.9, // phone_key match, or email_norm match
  MEDIUM: 0.6, // same normalised name + same company, different contact details
};

function dupConfidence(a, b) {
  if (a.phone_key && a.phone_key === b.phone_key) return { score: 1.0, on: 'phone_key' };
  if (a.email_norm && a.email_norm === b.email_norm) return { score: 0.95, on: 'email_norm' };
  const n = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');
  if (n(a.full_name) && n(a.full_name) === n(b.full_name)) {
    if (n(a.company) && n(a.company) === n(b.company)) return { score: 0.75, on: 'name+company' };
    if (a.domain && a.domain === b.domain) return { score: 0.7, on: 'name+domain' };
    return { score: 0.4, on: 'name only' };
  }
  return { score: 0, on: 'none' };
}

// ---------------------------------------------------------------------------
// 5. Deterministic scoring
// ---------------------------------------------------------------------------
// The AI contributes ZERO points. If the whole AI layer is deleted, every
// lead still scores, routes, assigns and syncs. That separation is what makes
// requirement D's "deterministic score" and "separate qualitative
// classification" two genuinely independent axes rather than one dressed up
// as two.
//
// Every `unknown` band is worth real points, not zero. A WhatsApp lead has no
// email, therefore no domain, therefore no enrichment - and with zero-valued
// unknowns the arithmetic made it structurally impossible for any WhatsApp
// lead to reach 70. For a brief whose scenario centres on WhatsApp, that is a
// scoring bug, not a scoring policy.

const SCORE = {
  company_size: { '201+': 20, '51-200': 16, '11-50': 12, '1-10': 6, unknown: 12 },
  industry: { target: 15, adjacent: 8, unknown: 10 }, // `excluded` disqualifies outright
  market: { core: 10, adjacent: 6, unknown: 5, other: 2 },
  service: { high: 25, mid: 15, low: 5, unknown: 5 },
  urgency: { immediate: 10, this_quarter: 6, exploring: 2, unknown: 2 },
  completeness: { both: 6, one: 3 },
  source: { referral: 5, website: 5, whatsapp: 4, paid_social: 2, csv_import: 1 },
  budget: { high: 14, mid: 7, unknown: 0 },
  penalty: { competitor_or_jobseeker: -20, disposable_email: -10 },
  MAX: 100,
};

// Budget bands, in USD, defined ONCE. They were briefly defined twice - the
// scorer bucketed an amount and intake banded the same amount against different
// numbers - so the same lead could score differently depending on which path it
// arrived by. A threshold with two homes is a threshold that will disagree with
// itself.
const BUDGET_USD = { HIGH: 5000, MID: 1000 };

const TARGET_INDUSTRIES = ['technology', 'professional services', 'real estate', 'healthcare', 'education', 'logistics'];
const ADJACENT_INDUSTRIES = ['retail', 'manufacturing', 'hospitality', 'construction'];
// Out-of-scope verticals. Every agency has them; keeping the list as data
// rather than a hardcoded branch means changing it is a config edit.
const EXCLUDED_INDUSTRIES = ['gambling', 'alcohol', 'tobacco', 'adult', 'lending'];

const CORE_MARKETS = ['EG', 'AE', 'SA'];
const ADJACENT_MARKETS = ['QA', 'KW', 'BH', 'OM', 'JO'];

const HIGH_VALUE_SERVICES = ['automation', 'ai_agent', 'rag', 'integration', 'custom_app'];
const MID_VALUE_SERVICES = ['consulting', 'audit', 'training'];

const DISQUALIFY_PATTERNS = /\b(job|vacanc|hiring|cv|resume|internship|student|thesis|competitor|partnership offer|guest post|seo services|link building)\b/i;

// ---------------------------------------------------------------------------
// 6. Bands - the brief's business rules, verbatim
// ---------------------------------------------------------------------------

const BANDS = {
  VIP: { min: 90, label: 'vip' }, // or the strategic-account flag
  QUALIFIED: { min: 70, label: 'qualified' },
  NURTURE: { min: 40, label: 'nurture' },
  UNQUALIFIED: { min: 0, label: 'unqualified' },
};

function bandFor(score, strategic) {
  if (strategic || score >= 90) return 'vip';
  if (score >= 70) return 'qualified';
  if (score >= 40) return 'nurture';
  return 'unqualified';
}

// Ordinal distance is what the AI-vs-rules conflict rule compares.
const BAND_ORDINAL = { unqualified: 0, nurture: 1, qualified: 2, vip: 2 };

// ---------------------------------------------------------------------------
// 7. The AI contract
// ---------------------------------------------------------------------------

const AI_SCHEMA = {
  intent_level: 'high | medium | low',
  urgency: 'immediate | this_quarter | exploring | unknown',
  buying_signals: 'string[] , at most 3',
  reason: 'string, at most 200 chars, quoting the lead not inventing',
  confidence: 'number 0..1',
};

const AI_IMPLIED_BAND = { high: 'qualified', medium: 'nurture', low: 'unqualified' };

const CONFLICT = {
  MIN_CONFIDENCE: 0.7,
  MIN_BAND_DISTANCE: 2,
};

/**
 * "Materially conflicts" made numeric, because a reviewer will ask what
 * material means. One clause, two constants.
 *
 * Adjacent disagreement (qualified vs nurture) is expected noise around a cut
 * point and must NOT trigger review, or the manual queue becomes the default
 * path and the automation has achieved nothing.
 */
function materiallyConflicts(ruleBand, ai) {
  if (!ai || ai.ai_status !== 'ok') return false;
  if (Number(ai.ai_confidence) < CONFLICT.MIN_CONFIDENCE) return false;
  const aiBand = AI_IMPLIED_BAND[ai.ai_intent];
  if (!aiBand) return false;
  return Math.abs(BAND_ORDINAL[aiBand] - BAND_ORDINAL[ruleBand]) >= CONFLICT.MIN_BAND_DISTANCE;
}

// ---------------------------------------------------------------------------
// 8. Assignment - three rungs, then stop
// ---------------------------------------------------------------------------
// Deterministic so it is testable: least loaded first, ties broken by agent_id
// rather than by whatever order the table happened to return.

const ASSIGN_RUNGS = [
  'available AND handles the service category',
  'available, any category',
  'fallback owner, and raise an alert',
];

function pickOwner(agents, service, fallbackOwnerId) {
  const load = (a) => Number(a.open_leads || 0) / Math.max(1, Number(a.capacity || 1));
  const byLoad = (x, y) => load(x) - load(y) || String(x.agent_id).localeCompare(String(y.agent_id));
  // The fallback owner is the safety net, not a member of the rotation. They
  // are usually the sales manager: high capacity and every service category,
  // which on an idle roster means a low load ratio and a winning tie-break, so
  // leaving them in the pool quietly makes the manager the default owner of
  // everything. Rung 3 is where they belong, and rung 3 raises an alert.
  const free = agents.filter((a) => a.available
    && Number(a.open_leads) < Number(a.capacity)
    && String(a.agent_id) !== String(fallbackOwnerId));
  const matched = free.filter((a) => String(a.services || '').split(',').map((s) => s.trim()).includes(service));
  if (matched.length) return { agent_id: matched.sort(byLoad)[0].agent_id, rung: 1 };
  if (free.length) return { agent_id: free.sort(byLoad)[0].agent_id, rung: 2 };
  return { agent_id: fallbackOwnerId, rung: 3, alert: true };
}

// ---------------------------------------------------------------------------
// 9. Odoo stage map
